args.sql:
SELECT AVG(
    CAST(communication_details->>'keyword_match_count' AS numeric) / 
    CAST(communication_details->>'msg_count_total' AS numeric)
) AS avg_keyword_hit_density
FROM communications;

SELECT AVG(
    CAST(communication_details->>'keyword_match_count' AS numeric) / 
    CAST(communication_details->>'msg_count_total' AS numeric)
) AS avg_keyword_hit_density
FROM communications;

SELECT ROUND(
    STDDEV(CAST(communication_details->>'keyword_match_count' AS numeric) / 
           CAST(communication_details->>'msg_count_total' AS numeric)),
    3
) AS stddev_keyword_hit_density
FROM communications;

SELECT ROUND(
    STDDEV(CAST(communication_details->>'keyword_match_count' AS numeric) / 
           CAST(communication_details->>'msg_count_total' AS numeric)),
    3
) AS stddev_keyword_hit_density
FROM communications;
